return $input.all().map(({json}, index) => {
  const {candles} = json;
  if (!Array.isArray(candles)) throw new Error("Expected closed XAUUSD M1 candles");
  const signals = [];
  let zone = null, detected = 0;
  for (const [i, bar] of candles.entries()) {
    const start = Date.parse(bar.openTime), end = Date.parse(bar.closeTime);
    if (!Number.isFinite(start) || end - start !== 60000 ||
        ![bar.open,bar.high,bar.low,bar.close].every(p => Number.isFinite(p) && p > 0) ||
        bar.low > Math.min(bar.open,bar.close) || bar.high < Math.max(bar.open,bar.close)) {
      throw new Error("Invalid M1 candle");
    }
    if (i && start < Date.parse(candles[i-1].closeTime)) throw new Error("Unordered or overlapping M1 candles");
    if (i && start !== Date.parse(candles[i-1].closeTime)) zone = null;
    if (zone) {
      const {direction, low, high, created} = zone;
      const buy = direction === "BUY";
      const stop = buy ? low : high;
      const invalid = buy ? bar.low <= stop : bar.high >= stop;
      const reclaimed = buy ? bar.low <= high && bar.close > high : bar.high >= low && bar.close < low;
      if (invalid || i - created > 12) zone = null;
      else if (reclaimed) {
        const sign = buy ? 1 : -1;
        const risk = (bar.close - stop) * sign;
        const target = bar.close + sign * risk * 2;
        if (target > 0) signals.push({direction,stop,target,confirmedAt:bar.closeTime});
        zone = null;
      }
    }
    if (i < 2 || Date.parse(candles[i-2].openTime) !== start - 120000 ||
        Date.parse(candles[i-1].openTime) !== start - 60000) continue;
    const first = candles[i-2];
    if (bar.low > first.high) {
      zone = {direction:"BUY",low:first.high,high:bar.low,created:i};
      detected++;
    } else if (bar.high < first.low) {
      zone = {direction:"SELL",low:bar.high,high:first.low,created:i};
      detected++;
    }
  }
  return {json:{...json,signals,fvgDetected:detected,strategyVersion:"FVG_RETEST_RESEARCH_V1"},pairedItem:{item:index}};
});
